package com.ptms.service; import com.ptms.domain.*; import com.ptms.dto.*; import com.ptms.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class DepartmentService{private final DepartmentRepository r;public DepartmentService(DepartmentRepository r){this.r=r;}public List<DepartmentDto>all(){return r.findAllByOrderByNameAsc().stream().map(this::dto).toList();}public DepartmentDto save(DepartmentDto d){Department x=d.id()==null?new Department():r.findById(d.id()).orElseThrow();x.setName(d.name().trim());x.setDescription(d.description());x.setEnabled(d.enabled());return dto(r.save(x));}public void delete(Long id){r.deleteById(id);}private DepartmentDto dto(Department x){return new DepartmentDto(x.getId(),x.getName(),x.getDescription(),x.isEnabled());}}
